use crate::{
    twins::{self, CIndex, Function},
    Corpus, Rule,
};
use rayon::prelude::*;
use regex::Regex;
use std::path::Path;
use std::sync::LazyLock;

pub struct DroppedNullGuard;
pub(crate) const GEN_MARKERS: &[&str] = &[
    "automatically generated by rust-bindgen",
    "@generated",
    "Do not edit manually",
];
const NOT_PTR: &[&str] = &[
    "PAGE_SIZE",
    "PFN_NUMBER",
    "PHYSICAL_ADDRESS",
    "LPARAM",
    "PROPID",
    "PCI_SLOT_NUMBER",
];
pub(crate) static SKIP_PATH_RE: LazyLock<Regex> =
    LazyLock::new(|| crate::regexes::cached(r"(/target/|/\.responses/)").unwrap());
static STORE_A: LazyLock<Regex> = LazyLock::new(|| {
    crate::regexes::cached(r"\*\s*([A-Za-z_]\w*)\s*(?:\.\s*(?:add|offset)\s*\([^()]*\)\s*)?=")
        .unwrap()
});
static STORE_B: LazyLock<Regex> = LazyLock::new(|| {
    crate::regexes::cached(r"\(\s*\*\s*([A-Za-z_]\w*)\s*\)\s*\.\s*\w+(?:\s*\.\s*\w+)*\s*=").unwrap()
});
static ASSERT: LazyLock<Regex> =
    LazyLock::new(|| crate::regexes::cached(r"\b(?:NT_)?ASSERTM?(?:MSG)?\s*\(").unwrap());
static CALL: LazyLock<Regex> =
    LazyLock::new(|| crate::regexes::cached(r"\b([A-Za-z_]\w*)\s*\(").unwrap());

fn split_top(s: &str, commas: bool) -> Vec<String> {
    let mut out = Vec::new();
    let (mut depth, mut cur) = (0i32, String::new());
    for c in s.chars().chain(std::iter::once(',')) {
        if "<([{".contains(c) {
            depth += 1
        } else if ">)]}".contains(c) {
            depth -= 1
        }
        if c == ',' && depth == 0 {
            if !cur.trim().is_empty() || commas {
                out.push(std::mem::take(&mut cur));
            } else {
                cur.clear()
            }
        } else {
            cur.push(c)
        }
    }
    out
}
fn split_c_top(s: &str) -> Vec<String> {
    let mut out = Vec::new();
    let (mut depth, mut cur) = (0i32, String::new());
    for c in s.chars().chain(std::iter::once(',')) {
        if "([{".contains(c) {
            depth += 1;
        } else if ")] }".contains(c) && c != ' ' {
            depth -= 1;
        }
        if c == ',' && depth == 0 {
            if !cur.trim().is_empty() {
                out.push(std::mem::take(&mut cur));
            } else {
                cur.clear();
            }
        } else {
            cur.push(c);
        }
    }
    out
}
pub(crate) fn split_params(s: &str) -> Vec<(String, String)> {
    split_top(s, true)
        .into_iter()
        .filter_map(|part| {
            let (n, t) = part.split_once(':')?;
            let name = n.trim().strip_prefix("mut ").unwrap_or(n.trim());
            crate::regexes::cached(r"^[A-Za-z_]\w*$")
                .unwrap()
                .is_match(name)
                .then(|| (name.to_string(), t.trim().to_string()))
        })
        .collect()
}
pub(crate) fn is_pointer(ty: &str) -> bool {
    let t = ty.trim();
    if t.starts_with('*') {
        return true;
    }
    let last = t.rsplit("::").next().unwrap_or(t);
    crate::regexes::cached(r"^(?:P|LP)[A-Z][A-Z0-9_]*$")
        .unwrap()
        .is_match(last)
        && !NOT_PTR.contains(&last)
}
fn stores(body: &str) -> std::collections::BTreeMap<String, usize> {
    let mut matches = Vec::new();
    for (which, re) in [&*STORE_A, &*STORE_B].iter().enumerate() {
        for m in re.captures_iter(body) {
            let whole = m.get(0).unwrap();
            let at = whole.start();
            if which == 0
                && body[..at]
                    .chars()
                    .next_back()
                    .is_some_and(|c| c.is_alphanumeric() || c == '_' || c == ')' || c == ']')
            {
                continue;
            }
            if body[whole.end()..].starts_with('=') {
                continue;
            }
            matches.push((at, m[1].to_string()));
        }
    }
    matches.sort_by_key(|m| m.0);
    let mut out = std::collections::BTreeMap::new();
    for (at, name) in matches {
        out.entry(name).or_insert(at);
    }
    out
}
pub(crate) fn all_stores(body: &str) -> Vec<(String, usize, usize)> {
    let mut hits = Vec::new();
    for (which, re) in [&*STORE_A, &*STORE_B].iter().enumerate() {
        for m in re.captures_iter(body) {
            let whole = m.get(0).unwrap();
            let at = whole.start();
            if which == 0
                && body[..at]
                    .chars()
                    .next_back()
                    .is_some_and(|c| c.is_alphanumeric() || c == '_' || c == ')' || c == ']')
            {
                continue;
            }
            let end = whole.end();
            if body[end..].starts_with('=') {
                continue;
            }
            let semi = body[end..].find(';').map_or(end, |i| end + i + 1);
            hits.push((m[1].to_string(), at, semi));
        }
    }
    hits.sort_by_key(|h| h.1);
    hits
}

fn tested(body: &str) -> std::collections::HashSet<String> {
    let pats = [
        r"\b([A-Za-z_]\w*)\s*\.\s*(?:is_null|as_mut|as_ref)\s*\(",
        r"\(\s*([A-Za-z_]\w*)\s+as\s+[^;{}()]*\)\s*\.\s*is_null\s*\(",
        r"\b([A-Za-z_]\w*)\s*(?:==|!=)\s*(?:core::ptr::|ptr::)?null",
        r"null(?:_mut)?\s*(?:::<[^>]*>)?\s*\(\s*\)\s*(?:==|!=)\s*([A-Za-z_]\w*)\b",
        r"ARGUMENT_PRESENT!?\s*\(\s*([A-Za-z_]\w*)\b",
        r"\b([A-Za-z_]\w*)\s+as\s+(?:usize|isize|ULONG_PTR|u64|u32)\b",
        r"\b([A-Za-z_]\w*)\s+as\s+[^;{}()=!]*?(?:==|!=)\s*(?:core::ptr::|ptr::)?null",
        r"\b([A-Za-z_]\w*)\s*(?:==|!=)\s*0\b",
        r"NonNull::new\s*\(\s*([A-Za-z_]\w*)\b",
    ];
    let mut out = std::collections::HashSet::new();
    for p in pats {
        let re = crate::regexes::cached(p).unwrap();
        for c in re.captures_iter(body) {
            out.insert(c[1].to_string());
        }
    }
    out
}
pub(crate) fn c_param_names(params: &str) -> Vec<String> {
    split_c_top(params)
        .into_iter()
        .filter_map(|part| {
            let re = crate::regexes::cached(r"\[[^\]]*\]").unwrap();
            let clean = re.replace_all(&part, "");
            let ids: Vec<_> = crate::regexes::cached(r"[A-Za-z_]\w*")
                .unwrap()
                .find_iter(&clean)
                .map(|m| m.as_str())
                .collect();
            if ids.is_empty() || ids == ["void"] {
                None
            } else {
                Some(ids.last().unwrap().to_string())
            }
        })
        .collect()
}
fn norm(s: &str) -> String {
    s.chars()
        .filter(|&c| c != '_')
        .flat_map(char::to_lowercase)
        .collect()
}
pub(crate) fn _split_top(s: &str) -> Vec<String> {
    split_c_top(s)
}
pub(crate) fn _match_paren(text: &str, open: usize) -> Option<usize> {
    match_close(text, open)
}

pub(crate) fn c_name_for(rust: &[(String, String)], idx: usize, c: &[String]) -> Option<String> {
    if rust.len() == c.len() {
        return c.get(idx).cloned();
    }
    let want = norm(&rust[idx].0);
    c.iter().find(|n| norm(n) == want).cloned()
}
fn bare_occurs(body: &str, p: &str) -> Vec<usize> {
    let mut out = Vec::new();
    let mut pos = 0;
    while let Some(i) = body[pos..].find(p) {
        let at = pos + i;
        let end = at + p.len();
        pos = end;
        let before = body[..at].chars().next_back();
        let after = body[end..].chars().next();
        if before
            .is_some_and(|c| c.is_alphanumeric() || c == '_' || c == '*' || c == '.' || c == '>')
            || after.is_some_and(|c| c.is_alphanumeric() || c == '_')
        {
            continue;
        }
        let tail = body[end..].trim_start();
        if tail.starts_with("->") || tail.starts_with('.') || tail.starts_with('[') {
            continue;
        }
        out.push(at)
    }
    out
}
fn in_assert(body: &str, at: usize) -> bool {
    let start = [
        body[..at].rfind(';'),
        body[..at].rfind('{'),
        body[..at].rfind('}'),
    ]
    .into_iter()
    .flatten()
    .max()
    .map_or(0, |x| x + 1);
    ASSERT.is_match(&body[start..=(at.min(body.len() - 1))])
}
fn c_test(name: &str, body: &str) -> Option<String> {
    for at in bare_occurs(body, name) {
        let pre = body[..at].trim_end();
        let post = body[at + name.len()..].trim_start();
        let direct_if = crate::regexes::cached(r"(?s)\bif\s*\(\s*!?$")
            .unwrap()
            .is_match(pre)
            && post.starts_with(')');
        let compare = crate::regexes::cached(r"^(?:==|!=)\s*(?:NULL|0)\b")
            .unwrap()
            .is_match(post)
            || crate::regexes::cached(r"\bNULL\s*(?:==|!=)$")
                .unwrap()
                .is_match(pre);
        let mut prefix = pre;
        if prefix.ends_with('!') {
            prefix = prefix[..prefix.len() - 1].trim_end();
        }
        let boolean = (prefix.ends_with('(') || prefix.ends_with("&&") || prefix.ends_with("||"))
            && (post.starts_with("&&") || post.starts_with("||") || post.starts_with('?'));
        let arg = crate::regexes::cached(&format!(r"(?s)\bARGUMENT_PRESENT\s*\(\s*$"))
            .unwrap()
            .is_match(pre)
            && post.starts_with(')');
        if (direct_if || compare || boolean || arg) && !in_assert(body, at) {
            let lo = body[..at].rfind('\n').map_or(0, |x| x + 1);
            let hi = body[at..].find('\n').map_or(body.len(), |x| at + x);
            return Some(
                body[lo..hi]
                    .split_whitespace()
                    .collect::<Vec<_>>()
                    .join(" ")
                    .chars()
                    .take(110)
                    .collect(),
            );
        }
    }
    None
}
fn c_derefs(name: &str, body: &str) -> bool {
    let mut from = 0;
    while let Some(rel) = body[from..].find(name) {
        let at = from + rel;
        let end = at + name.len();
        from = end;
        if body[..at]
            .chars()
            .next_back()
            .is_some_and(|c| c.is_alphanumeric() || c == '_')
            || body[end..]
                .chars()
                .next()
                .is_some_and(|c| c.is_alphanumeric() || c == '_')
        {
            continue;
        }
        let pre = body[..at].trim_end();
        let post = body[end..].trim_start();
        let star = pre.ends_with('*')
            && pre[..pre.len() - 1].chars().next_back().map_or(true, |c| {
                !(c.is_alphanumeric() || c == '_' || c == ')' || c == ']')
            });
        if star || post.starts_with("->") || post.starts_with('[') {
            return true;
        }
    }
    false
}
fn match_close(text: &str, open: usize) -> Option<usize> {
    let mut d = 0;
    for (i, c) in text.char_indices().skip_while(|(i, _)| *i < open) {
        if c == '(' {
            d += 1
        } else if c == ')' {
            d -= 1;
            if d == 0 {
                return Some(i);
            }
        }
    }
    None
}
fn c_guard(twin: &Function, name: &str, index: &CIndex, depth: u8) -> Option<String> {
    let ev = c_test(name, &twin.body);
    if ev.is_some() || depth == 0 || c_derefs(name, &twin.body) {
        return ev;
    }
    for m in CALL.captures_iter(&twin.body) {
        let callee = &m[1];
        if ["if", "while", "for", "switch", "return", "sizeof"].contains(&callee) {
            continue;
        }
        let whole = m.get(0).unwrap();
        let open = whole.end() - 1;
        let Some(close) = match_close(&twin.body, open) else {
            continue;
        };
        let args = split_top(&twin.body[whole.end()..close], false)
            .into_iter()
            .map(|s| s.trim().to_string())
            .collect::<Vec<_>>();
        let Some(pos) = args.iter().position(|a| a == name) else {
            continue;
        };
        for sub in index.in_file(&twin.path, callee).iter() {
            let names = c_param_names(&sub.params);
            if names.len() == args.len() {
                if let Some(ev) = c_guard(sub, &names[pos], index, depth - 1) {
                    return Some(format!("{}(): {}", callee, ev));
                }
            }
        }
    }
    None
}
fn generated(text: &str) -> bool {
    let prefix: String = text.chars().take(2000).collect();
    GEN_MARKERS.iter().any(|g| prefix.contains(g))
}
fn candidates(file: &crate::SourceFile, root: &Path, index: &CIndex) -> Vec<String> {
    let raw = &file.text;
    if generated(raw) {
        return vec![];
    }
    let rel = file.path.to_string_lossy();
    if rel.contains("/target/") || rel.contains("/.responses/") {
        return vec![];
    }
    let abs = root.join(&file.path);
    let funcs = file.twin_functions(root);
    let lines: Vec<_> = raw.split('\n').collect();
    let mut out = vec![];
    for f in funcs {
        let stored = stores(&f.body);
        if stored.is_empty() {
            continue;
        }
        let params = split_params(&f.params);
        let checked = tested(&f.body);
        for (i, (name, ty)) in params.iter().enumerate() {
            let Some(&off) = stored.get(name) else {
                continue;
            };
            if !is_pointer(ty) || checked.contains(name) {
                continue;
            }
            let at = f.body_start + off;
            let line = file.line(at);
            if lines.get(line - 1).is_some_and(|l| {
                crate::regexes::cached(r"//\s*nolint(?::\s*dropped-null-guard\b|\s*$)")
                    .unwrap()
                    .is_match(l)
            }) {
                continue;
            }
            let twins = twins::prefer(&abs, index.get(&f.name));
            let Some(best) = twins.first() else { continue };
            if twins::affinity(&abs, best) == 0 {
                continue;
            }
            let cname = c_name_for(&params, i, &c_param_names(&best.params));
            let Some(cname) = cname else { continue };
            let Some(ev) = c_guard(best, &cname, index, 1) else {
                continue;
            };
            let src = lines.get(line - 1).unwrap_or(&"").trim();
            out.push(format!(
                "{}:{}: dropped-null-guard {}({})",
                file.path.display(),
                line,
                f.name,
                name
            ));
            let _ = (src, ev);
        }
    }
    out
}
impl Rule for DroppedNullGuard {
    fn name(&self) -> &'static str {
        "scan_dropped_null_guard"
    }
    fn needs_c_twins(&self) -> bool {
        true
    }
    fn run(&self, c: &Corpus) -> Result<Vec<String>, String> {
        Ok(c.rust_files()
            .par_bridge()
            .flat_map_iter(|f| candidates(f, &c.root, c.c_twins()))
            .collect())
    }
}
#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn params_and_types() {
        assert_eq!(
            split_params("format: u16, mut final_size: *mut u32, x: Option<(u32,u32)>").len(),
            3
        );
        assert!(is_pointer("*const u8"));
        assert!(is_pointer("PULONG"));
        assert!(!is_pointer("LPARAM"));
    }
    #[test]
    fn rust_store_and_guard() {
        let s = "unsafe fn f(out: *mut u32) { *out = 1; }";
        let blank = twins::blank_rust(s);
        let f = twins::rust_functions(&blank, Path::new("x.rs")).remove(0);
        assert_eq!(stores(&f.body).get("out"), Some(&2));
        assert!(!tested(&f.body).contains("out"));
        let g = "unsafe fn f(out: *mut u32) { if !out.is_null() { *out = 1; } }";
        let blank = twins::blank_rust(g);
        let f = twins::rust_functions(&blank, Path::new("x.rs")).remove(0);
        assert!(tested(&f.body).contains("out"));
    }
    #[test]
    fn c_guard_and_assert() {
        assert!(c_test("p", "if (p) *p = 1;").is_some());
        assert!(c_test("p", "ASSERT(p != NULL);").is_none());
        assert!(c_derefs("p", "*p = 1;"));
    }
    #[test]
    fn reversed_c_comparison_keeps_the_legacy_null_only_boundary() {
        assert!(c_test("p", "if (NULL == p) *p = 1;").is_some());
        assert!(c_test("p", "if (0 == p) *p = 1;").is_none());
        assert!(c_test("p", "if (FOONULL == p) *p = 1;").is_none());
    }
    #[test]
    fn generated_prefix_counts_characters_without_splitting_utf8() {
        let text = format!("{}@generated", "é".repeat(1990));
        assert!(generated(&text));
    }
    #[test]
    fn null_on_left_is_a_test() {
        assert!(tested("if core::ptr::null_mut() != p { *p = 1; }").contains("p"));
        assert!(tested("if null_mut::<u8>() == p { return; }").contains("p"));
    }
    #[test]
    fn oracle_positive_and_negative() {
        let rust=crate::SourceFile::new("sdk/lib/rust/compress/src/lib.rs".into(),"pub unsafe fn RtlDecompressFragment(format:u16, uncompressed:*mut u8, size:u32, compressed:*const u8, compressed_size:u32, offset:u32, final_size:*mut u32, workspace:*mut u8)->i32 { *final_size=0; 0 }".into());
        let c=crate::SourceFile::new("sdk/lib/rtl/compress.c".into(),"int RtlDecompressFragment(int format, char *uncompressed, int size, const char *compressed, int cs, int off, unsigned *final_size, char *workspace) { lznt1_decompress(final_size); return 0; }\nnamespace { void lznt1_decompress(unsigned *final_size) { if (final_size) *final_size = 0; } }".into());
        let corpus = Corpus::new(std::path::PathBuf::from("/repo"), vec![rust, c]);
        assert!(corpus.c_twins().get("lznt1_decompress").is_empty());
        assert_eq!(
            corpus
                .c_twins()
                .in_file(
                    &std::path::PathBuf::from("sdk/lib/rtl/compress.c"),
                    "lznt1_decompress"
                )
                .len(),
            1
        );
        assert!(DroppedNullGuard
            .run(&corpus)
            .unwrap()
            .iter()
            .any(|x| x.contains("RtlDecompressFragment(final_size)")));
    }
}
